insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (78, 4, 148, 162, 'سورة النساء ١٤٨ – ١٦٢', 'لا يحب الله الجهر بالسوء، وجرائم أهل الكتاب، ورفع عيسى ﵇', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 78) = $j$[{"lbl": "الآيتان ١٤٨ – ١٤٩", "q": "۞لَّا يُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوٓءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا ﴿١٤٨﴾ إِن تُبۡدُواْ خَيۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُواْ عَن سُوٓءٖ فَإِنَّ ٱللَّهَ كَانَ عَفُوّٗا قَدِيرًا ﴿١٤٩﴾", "w": [["السوء", "ما يسوء من قيل فيه أو فُعل به."], ["سميعاً عليماً", "سميعاً للأقوال، عليماً بالأعمال."], ["إن تُبدوا", "تُظهروا ولا تُخفوا."], ["تعفوا عن سوء", "لا تؤاخذوا به."]], "m": "يخبر الله أنه لا يحب الجهر بالسوء من القول، ولازم هذا أن عباده المؤمنين يجب أن يكرهوا ما يكره ربهم ويحبّوا ما يحب، وهذا شرط الولاية، ثم استثنى المظلوم، فله أن يجهر بمظلمته لدى الحاكم ليُرفع عنه الظلم، وكان الله سميعاً عليماً، فليُتّقَ فلا يُعصى بفعل السوء ولا بقوله. ثم ندب عباده المؤمنين إلى فعل الخير في السر أو العلن، وإلى العفو عن صاحب السوء: إن تبدوا خيراً أو تخفوه أو تعفوا عن سوء فإن الله كان عفوّاً قديراً؛ ففاعل الخير سيكسب خيراً أبداه أو أخفاه، وصاحب العفو سيعفو الله عنه حين تزلّ قدمه، شكراً لعفوه السابق.", "h": ["حرمة الجهر بالسوء، والسرّ به كذلك، فلا يحل لمؤمن ولا مؤمنة أن ينطق بما يسوء القلوب والنفوس، إلا في حالة الشكوى وإظهار الظلم لا غير.", "استحباب فعل الخير، وسرّه كجهره، لا ينقص أجره بالجهر ولا يزيد بالسر.", "استحباب العفو عن المؤمن إذا بدا منه سوء، ومن يعفُ يعفُ الله عنه."], "k": "هل يخرج من لساني اليوم ما يسوء أحداً؟ ومن أحتاج أن أعفو عنه لأرجو عفو الله؟"}, {"lbl": "الآيات ١٥٠ – ١٥٢", "q": "إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ وَيُرِيدُونَ أَن يَتَّخِذُواْ بَيۡنَ ذَٰلِكَ سَبِيلًا ﴿١٥٠﴾ أُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ حَقّٗاۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا ﴿١٥١﴾ وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ يُفَرِّقُواْ بَيۡنَ أَحَدٖ مِّنۡهُمۡ أُوْلَـٰٓئِكَ سَوۡفَ يُؤۡتِيهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿١٥٢﴾", "w": [["ورسله", "جمع رسول، وهم جمّ غفير."], ["سبيلاً", "طريقاً بين الكفر والإيمان، وليس ثَمّ إلا طريق واحد: فمن آمن بكل الرسل فهو المؤمن، ومن آمن بالبعض وكفر بالبعض فهو الكافر كمن لم يؤمن بأحد منهم."], ["ولم يفرّقوا", "كما فرّق اليهود فآمنوا بموسى وكفروا بعيسى ومحمد ﷺ، وكما فرّق النصارى فآمنوا بموسى وعيسى وكفروا بمحمد ﷺ."], ["أجورهم", "أجر إيمانهم برسل الله وعملهم الصالح، وهو الجنة."]], "m": "يقرّر الله حكمه على اليهود والنصارى بالكفر الحق: إن الذين يكفرون بالله ورسله، ويريدون أن يفرّقوا بين الله ورسله، ويقولون نؤمن ببعض ونكفر ببعض، ويريدون أن يتخذوا بين ذلك طريقاً إلى مذهب باطل، وهو التخيّر بين رسل الله، أولئك هم الكافرون حقاً، وأعتدنا للكافرين عذاباً مهيناً جزاء كبريائهم. فسجّل عليهم الكفر ثلاث مرات، وأظهر في موضع الإضمار في قوله «للكافرين» للإشارة إلى علّة الحكم. ثم قابلها بالآية التي بعدها: والذين آمنوا بالله ورسله ولم يفرّقوا بين أحد منهم، أولئك سوف يؤتيهم أجورهم، وكان الله غفوراً رحيماً، فيغفر ذنوبهم ويُدخلهم دار كرامته.", "h": ["تقرير كفر اليهود والنصارى، لفساد عقائدهم وبطلان أعمالهم.", "كفر من كذّب بالله ورسوله ولو في شيء واحد مما وجب الإيمان به.", "بطلان إيمان من يؤمن ببعض الرسل ويكفر ببعض.", "صحة الدين الإسلامي وبطلان اليهودية والنصرانية، حيث أوعد تعالى اليهود والنصارى بالعذاب المهين، ووعد المؤمنين بتوفية أجورهم والمغفرة والرحمة لهم."], "k": "هل أؤمن بالقرآن كله، أم آخذ منه ما يوافق هواي وأتجاهل الباقي؟"}, {"lbl": "الآيتان ١٥٣ – ١٥٤", "q": "يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ مُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُواْ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ فَعَفَوۡنَا عَن ذَٰلِكَۚ وَءَاتَيۡنَا مُوسَىٰ سُلۡطَٰنٗا مُّبِينٗا ﴿١٥٣﴾ وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُلۡنَا لَهُمۡ لَا تَعۡدُواْ فِي ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا ﴿١٥٤﴾", "w": [["جهرة", "عياناً نشاهده ونراه بأبصارنا."], ["الصاعقة", "صوت حادّ ورجفة عنيفة صُعقوا بها."], ["اتخذوا العجل", "إلهاً فعبدوه."], ["فعفونا عن ذلك", "لم نؤاخذهم به."], ["سلطاناً مبيناً", "حجة واضحة وقدرة كاملة قهر بها أعداءه."], ["ورفعنا فوقهم الطور", "جبل الطور بسيناء."], ["ادخلوا الباب سُجّداً", "راكعين متواضعين خاشعين لله شكراً لنعمه عليهم."], ["لا تعدوا", "لا تعتدوا، أي لا تتجاوزوا ما حُدّ لكم."], ["ميثاقاً غليظاً", "عهداً مؤكداً بالأيمان."]], "m": "لما نعى الله على أهل الكتاب تفريقهم بين الرسل، قال لرسوله ﷺ: إن سألك اليهود أن تنزل عليهم كتاباً من السماء فلا تعجب ولا تحفل به، فهذا دأبهم، فقد سألوا موسى أكبر من ذلك فقالوا: أرنا الله جهرة، فأخذتهم الصاعقة بظلمهم، ثم اتخذوا العجل إلهاً في غياب موسى من بعد ما رأوا البيّنات، إذ فلق الله لهم البحر وأنجاهم وأغرق عدوهم، ومع هذا عفا الله عنهم، وآتى موسى حجة واضحة، فلم يؤثّر ذلك في طباعهم. ورفع فوقهم الطور تهديداً لما امتنعوا أن يتعهدوا بالعمل بالتوراة، فخافوا فتعهدوا ثم نقضوا. وأمرهم حين فتح يوشع بن نون بيت المقدس أن يدخلوا الباب خاضعين شكراً لله، فدخلوه زحفاً على أستاههم عناداً، ونهاهم عن الصيد في السبت فاعتدوا، وأخذ منهم ميثاقاً غليظاً على العمل بما شرع لهم، فعصوا وتمرّدوا؛ فلا غرابة في سؤالهم إياك.", "h": ["تعنّت أهل الكتاب إزاء الدعوة الإسلامية، وكفرهم بها على علم أنها دعوة حق.", "بيان قبائح اليهود وخبثهم الملازم لهم طوال حياتهم.", "نقض اليهود للعهود والمواثيق أصبح طبعاً لهم لا يفارقهم، ولذا وجب عدم الثقة في عهودهم ومواثيقهم."], "k": "عفا الله عنهم مرة بعد مرة فلم يتغيّروا… كم مرة عفا عني ربي؟ وهل تغيّرت؟"}, {"lbl": "الآيات ١٥٥ – ١٥٩", "q": "فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ وَكُفۡرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا ﴿١٥٥﴾ وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ بُهۡتَٰنًا عَظِيمٗا ﴿١٥٦﴾ وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِيحَ عِيسَى ٱبۡنَ مَرۡيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِ لَفِي شَكّٖ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ يَقِينَۢا ﴿١٥٧﴾ بَل رَّفَعَهُ ٱللَّهُ إِلَيۡهِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا ﴿١٥٨﴾ وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ إِلَّا لَيُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكُونُ عَلَيۡهِمۡ شَهِيدٗا ﴿١٥٩﴾", "w": [["فبما نقضهم", "الباء سببية، أي فبسبب نقضهم ميثاقهم، والنقض: الحلّ بعد الإبرام."], ["بغير حق", "بدون موجب لقتلهم، ولا موجب لقتل الأنبياء قط."], ["غُلف", "جمع أغلف، وهو ما عليه غلاف يمنعه من وصول المعرفة والعلم إليه."], ["بهتاناً عظيماً", "البهتان: الكذب الذي يحيّر من قيل فيه، والمراد رميهم مريم بالزنى."], ["وما صلبوه", "لم يصلبوه، والصلب: شدّه على خشبة وقتله عليها."], ["وإن من أهل الكتاب", "ما من أحد منهم إلا ليؤمننّ عند حضور الموت أن عيسى عبد الله ورسوله."]], "m": "ما زال السياق في بيان جرائم اليهود التي كانت سبباً في لعنهم وغضب الله عليهم: نقضهم المواثيق وخاصة عهدهم بالعمل بالتوراة، وكفرهم بآيات الله المنزلة على عيسى ومحمد ﷺ، وقتلهم الأنبياء كزكريا ويحيى، وقولهم: قلوبنا غلف لا تقبل دعوة الإسلام، فكذّبهم الله وأخبر أنه طبع عليها بكفرهم، فلا يؤمنون إلا قليلاً. وكفرهم بعيسى، وقولهم على مريم بهتاناً عظيماً إذ رموها بالفاحشة، وقولهم: إنا قتلنا المسيح عيسى ابن مريم رسول الله، وما قتلوه وما صلبوه، ولكن أُلقي شبهه على رجل آخر ظنّوه هو فصلبوه وقتلوه، وأما المسيح فرفعه الله إليه، وكان الله عزيزاً حكيماً. والذين اختلفوا فيه لفي شك منه، لم يجزموا أبداً أن من صلبوه هو المسيح، ما لهم به من علم إلا اتباع الظن، وما قتلوه يقيناً. ثم أخبر أنه ما من يهودي ولا نصراني يحضره الموت إلا آمن بأن عيسى عبد الله ورسوله، لا ابن زنى ولا ساحر كما يعتقد اليهود، ولا هو الله ولا ابن الله كما يعتقد النصارى، ولكن هذا الإيمان لا ينفعه لأنه عند معاينة الموت، ويوم القيامة يكون عيسى عليهم شهيداً.", "h": ["بيان جرائم اليهود.", "بطلان اعتقاد النصارى أن عيسى صُلب وقُتل، أما اليهود فإنهم وإن لم يقتلوه فهم مؤاخذون على قصدهم، حيث صلبوا وقتلوا من ظنّوه عيسى ﵇.", "تقرير رفع عيسى ﵇ إلى السماء، ونزوله في آخر أيام الدنيا."], "k": "«بل طبع الله عليها بكفرهم»… هل في قلبي «غلاف» يمنعني من قبول نصيحة أو حق؟"}, {"lbl": "الآيات ١٦٠ – ١٦٢", "q": "فَبِظُلۡمٖ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرٗا ﴿١٦٠﴾ وَأَخۡذِهِمُ ٱلرِّبَوٰاْ وَقَدۡ نُهُواْ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمٗا ﴿١٦١﴾ لَّـٰكِنِ ٱلرَّـٰسِخُونَ فِي ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أُوْلَـٰٓئِكَ سَنُؤۡتِيهِمۡ أَجۡرًا عَظِيمًا ﴿١٦٢﴾", "w": [["فبظلم", "الباء سببية، أي فبسبب ظلمهم."], ["هادوا", "اليهود، إذ قالوا: إنا هُدنا إليك."], ["وأخذهم الربا", "قبوله والتعامل به وأكله."], ["الراسخون في العلم", "أصحاب القدم الثابتة في معرفة الله وشرائعه، علومهم يقينيات لا ظنيات."]], "m": "ما زال السياق في كشف عظائم ذنوب اليهود: فسجّل عليهم الظلم العظيم الذي استوجبوا به أن حرّم الله عليهم طيبات كثيرة كانت حلالاً لهم، وصدّهم أنفسهم وغيرهم عن سبيل الله كثيراً بجحودهم الحق وتحريفهم كلام الله وقبولهم الرشوة في إبطال الأحكام. ثم سجّل جرائم أخرى: استباحتهم الربا وقد نُهوا عنه، وأكلهم أموال الناس بالباطل كالرشوة والفتاوى الباطلة، وأعدّ لمن مات منهم على الكفر عذاباً أليماً. ثم نزلت الآية الثالثة في عبد الله بن سلام وبعض علماء اليهود الذين آمنوا: لكن الراسخون في العلم منهم، الذين علومهم يقينية، والمؤمنون من هذه الأمة، يؤمنون بما أُنزل إليك وما أُنزل من قبلك، والمقيمين الصلاة، والمؤتون الزكاة، والمؤمنون بالله واليوم الآخر، أولئك سنؤتيهم أجراً عظيماً لا يُقدر قدره.", "h": ["المعاصي تورث الحرمان من خير الدنيا والآخرة.", "حرمة الصدّ عن الإسلام، ولو بالسلوك الشائن والمعاملة الباطلة.", "حرمة الربا، وأنه موجب للعقوبة في الدنيا والآخرة.", "حرمة أكل أموال الناس بالباطل كالسرقة والغش والرشوة.", "من أهل الكتاب صلحاء ربانيون، كعبد الله بن سلام وآخرين.", "الرسوخ في العلم يأمن صاحبه الزلّات والوقوع في المهلكات.", "فضل إقام الصلاة، لنصب «والمقيمين الصلاة» في الآية على المدح والتخصيص."], "k": "هل حرمتني معصيةٌ من خيرٍ كنت أجده: قيام ليل، أو لذة مناجاة، أو بركة رزق؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 78;
insert into public.tdb_cards(topic, i, body) select 78, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٤٨ – ١٤٩", "q": "۞لَّا يُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوٓءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا ﴿١٤٨﴾ إِن تُبۡدُواْ خَيۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُواْ عَن سُوٓءٖ فَإِنَّ ٱللَّهَ كَانَ عَفُوّٗا قَدِيرًا ﴿١٤٩﴾", "w": [["السوء", "ما يسوء من قيل فيه أو فُعل به."], ["سميعاً عليماً", "سميعاً للأقوال، عليماً بالأعمال."], ["إن تُبدوا", "تُظهروا ولا تُخفوا."], ["تعفوا عن سوء", "لا تؤاخذوا به."]], "m": "يخبر الله أنه لا يحب الجهر بالسوء من القول، ولازم هذا أن عباده المؤمنين يجب أن يكرهوا ما يكره ربهم ويحبّوا ما يحب، وهذا شرط الولاية، ثم استثنى المظلوم، فله أن يجهر بمظلمته لدى الحاكم ليُرفع عنه الظلم، وكان الله سميعاً عليماً، فليُتّقَ فلا يُعصى بفعل السوء ولا بقوله. ثم ندب عباده المؤمنين إلى فعل الخير في السر أو العلن، وإلى العفو عن صاحب السوء: إن تبدوا خيراً أو تخفوه أو تعفوا عن سوء فإن الله كان عفوّاً قديراً؛ ففاعل الخير سيكسب خيراً أبداه أو أخفاه، وصاحب العفو سيعفو الله عنه حين تزلّ قدمه، شكراً لعفوه السابق.", "h": ["حرمة الجهر بالسوء، والسرّ به كذلك، فلا يحل لمؤمن ولا مؤمنة أن ينطق بما يسوء القلوب والنفوس، إلا في حالة الشكوى وإظهار الظلم لا غير.", "استحباب فعل الخير، وسرّه كجهره، لا ينقص أجره بالجهر ولا يزيد بالسر.", "استحباب العفو عن المؤمن إذا بدا منه سوء، ومن يعفُ يعفُ الله عنه."], "k": "هل يخرج من لساني اليوم ما يسوء أحداً؟ ومن أحتاج أن أعفو عنه لأرجو عفو الله؟"}, {"lbl": "الآيات ١٥٠ – ١٥٢", "q": "إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ وَيُرِيدُونَ أَن يَتَّخِذُواْ بَيۡنَ ذَٰلِكَ سَبِيلًا ﴿١٥٠﴾ أُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ حَقّٗاۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا ﴿١٥١﴾ وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ يُفَرِّقُواْ بَيۡنَ أَحَدٖ مِّنۡهُمۡ أُوْلَـٰٓئِكَ سَوۡفَ يُؤۡتِيهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿١٥٢﴾", "w": [["ورسله", "جمع رسول، وهم جمّ غفير."], ["سبيلاً", "طريقاً بين الكفر والإيمان، وليس ثَمّ إلا طريق واحد: فمن آمن بكل الرسل فهو المؤمن، ومن آمن بالبعض وكفر بالبعض فهو الكافر كمن لم يؤمن بأحد منهم."], ["ولم يفرّقوا", "كما فرّق اليهود فآمنوا بموسى وكفروا بعيسى ومحمد ﷺ، وكما فرّق النصارى فآمنوا بموسى وعيسى وكفروا بمحمد ﷺ."], ["أجورهم", "أجر إيمانهم برسل الله وعملهم الصالح، وهو الجنة."]], "m": "يقرّر الله حكمه على اليهود والنصارى بالكفر الحق: إن الذين يكفرون بالله ورسله، ويريدون أن يفرّقوا بين الله ورسله، ويقولون نؤمن ببعض ونكفر ببعض، ويريدون أن يتخذوا بين ذلك طريقاً إلى مذهب باطل، وهو التخيّر بين رسل الله، أولئك هم الكافرون حقاً، وأعتدنا للكافرين عذاباً مهيناً جزاء كبريائهم. فسجّل عليهم الكفر ثلاث مرات، وأظهر في موضع الإضمار في قوله «للكافرين» للإشارة إلى علّة الحكم. ثم قابلها بالآية التي بعدها: والذين آمنوا بالله ورسله ولم يفرّقوا بين أحد منهم، أولئك سوف يؤتيهم أجورهم، وكان الله غفوراً رحيماً، فيغفر ذنوبهم ويُدخلهم دار كرامته.", "h": ["تقرير كفر اليهود والنصارى، لفساد عقائدهم وبطلان أعمالهم.", "كفر من كذّب بالله ورسوله ولو في شيء واحد مما وجب الإيمان به.", "بطلان إيمان من يؤمن ببعض الرسل ويكفر ببعض.", "صحة الدين الإسلامي وبطلان اليهودية والنصرانية، حيث أوعد تعالى اليهود والنصارى بالعذاب المهين، ووعد المؤمنين بتوفية أجورهم والمغفرة والرحمة لهم."], "k": "هل أؤمن بالقرآن كله، أم آخذ منه ما يوافق هواي وأتجاهل الباقي؟"}, {"lbl": "الآيتان ١٥٣ – ١٥٤", "q": "يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ مُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُواْ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ فَعَفَوۡنَا عَن ذَٰلِكَۚ وَءَاتَيۡنَا مُوسَىٰ سُلۡطَٰنٗا مُّبِينٗا ﴿١٥٣﴾ وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُلۡنَا لَهُمۡ لَا تَعۡدُواْ فِي ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا ﴿١٥٤﴾", "w": [["جهرة", "عياناً نشاهده ونراه بأبصارنا."], ["الصاعقة", "صوت حادّ ورجفة عنيفة صُعقوا بها."], ["اتخذوا العجل", "إلهاً فعبدوه."], ["فعفونا عن ذلك", "لم نؤاخذهم به."], ["سلطاناً مبيناً", "حجة واضحة وقدرة كاملة قهر بها أعداءه."], ["ورفعنا فوقهم الطور", "جبل الطور بسيناء."], ["ادخلوا الباب سُجّداً", "راكعين متواضعين خاشعين لله شكراً لنعمه عليهم."], ["لا تعدوا", "لا تعتدوا، أي لا تتجاوزوا ما حُدّ لكم."], ["ميثاقاً غليظاً", "عهداً مؤكداً بالأيمان."]], "m": "لما نعى الله على أهل الكتاب تفريقهم بين الرسل، قال لرسوله ﷺ: إن سألك اليهود أن تنزل عليهم كتاباً من السماء فلا تعجب ولا تحفل به، فهذا دأبهم، فقد سألوا موسى أكبر من ذلك فقالوا: أرنا الله جهرة، فأخذتهم الصاعقة بظلمهم، ثم اتخذوا العجل إلهاً في غياب موسى من بعد ما رأوا البيّنات، إذ فلق الله لهم البحر وأنجاهم وأغرق عدوهم، ومع هذا عفا الله عنهم، وآتى موسى حجة واضحة، فلم يؤثّر ذلك في طباعهم. ورفع فوقهم الطور تهديداً لما امتنعوا أن يتعهدوا بالعمل بالتوراة، فخافوا فتعهدوا ثم نقضوا. وأمرهم حين فتح يوشع بن نون بيت المقدس أن يدخلوا الباب خاضعين شكراً لله، فدخلوه زحفاً على أستاههم عناداً، ونهاهم عن الصيد في السبت فاعتدوا، وأخذ منهم ميثاقاً غليظاً على العمل بما شرع لهم، فعصوا وتمرّدوا؛ فلا غرابة في سؤالهم إياك.", "h": ["تعنّت أهل الكتاب إزاء الدعوة الإسلامية، وكفرهم بها على علم أنها دعوة حق.", "بيان قبائح اليهود وخبثهم الملازم لهم طوال حياتهم.", "نقض اليهود للعهود والمواثيق أصبح طبعاً لهم لا يفارقهم، ولذا وجب عدم الثقة في عهودهم ومواثيقهم."], "k": "عفا الله عنهم مرة بعد مرة فلم يتغيّروا… كم مرة عفا عني ربي؟ وهل تغيّرت؟"}, {"lbl": "الآيات ١٥٥ – ١٥٩", "q": "فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ وَكُفۡرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا ﴿١٥٥﴾ وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ بُهۡتَٰنًا عَظِيمٗا ﴿١٥٦﴾ وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِيحَ عِيسَى ٱبۡنَ مَرۡيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِ لَفِي شَكّٖ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ يَقِينَۢا ﴿١٥٧﴾ بَل رَّفَعَهُ ٱللَّهُ إِلَيۡهِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا ﴿١٥٨﴾ وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ إِلَّا لَيُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكُونُ عَلَيۡهِمۡ شَهِيدٗا ﴿١٥٩﴾", "w": [["فبما نقضهم", "الباء سببية، أي فبسبب نقضهم ميثاقهم، والنقض: الحلّ بعد الإبرام."], ["بغير حق", "بدون موجب لقتلهم، ولا موجب لقتل الأنبياء قط."], ["غُلف", "جمع أغلف، وهو ما عليه غلاف يمنعه من وصول المعرفة والعلم إليه."], ["بهتاناً عظيماً", "البهتان: الكذب الذي يحيّر من قيل فيه، والمراد رميهم مريم بالزنى."], ["وما صلبوه", "لم يصلبوه، والصلب: شدّه على خشبة وقتله عليها."], ["وإن من أهل الكتاب", "ما من أحد منهم إلا ليؤمننّ عند حضور الموت أن عيسى عبد الله ورسوله."]], "m": "ما زال السياق في بيان جرائم اليهود التي كانت سبباً في لعنهم وغضب الله عليهم: نقضهم المواثيق وخاصة عهدهم بالعمل بالتوراة، وكفرهم بآيات الله المنزلة على عيسى ومحمد ﷺ، وقتلهم الأنبياء كزكريا ويحيى، وقولهم: قلوبنا غلف لا تقبل دعوة الإسلام، فكذّبهم الله وأخبر أنه طبع عليها بكفرهم، فلا يؤمنون إلا قليلاً. وكفرهم بعيسى، وقولهم على مريم بهتاناً عظيماً إذ رموها بالفاحشة، وقولهم: إنا قتلنا المسيح عيسى ابن مريم رسول الله، وما قتلوه وما صلبوه، ولكن أُلقي شبهه على رجل آخر ظنّوه هو فصلبوه وقتلوه، وأما المسيح فرفعه الله إليه، وكان الله عزيزاً حكيماً. والذين اختلفوا فيه لفي شك منه، لم يجزموا أبداً أن من صلبوه هو المسيح، ما لهم به من علم إلا اتباع الظن، وما قتلوه يقيناً. ثم أخبر أنه ما من يهودي ولا نصراني يحضره الموت إلا آمن بأن عيسى عبد الله ورسوله، لا ابن زنى ولا ساحر كما يعتقد اليهود، ولا هو الله ولا ابن الله كما يعتقد النصارى، ولكن هذا الإيمان لا ينفعه لأنه عند معاينة الموت، ويوم القيامة يكون عيسى عليهم شهيداً.", "h": ["بيان جرائم اليهود.", "بطلان اعتقاد النصارى أن عيسى صُلب وقُتل، أما اليهود فإنهم وإن لم يقتلوه فهم مؤاخذون على قصدهم، حيث صلبوا وقتلوا من ظنّوه عيسى ﵇.", "تقرير رفع عيسى ﵇ إلى السماء، ونزوله في آخر أيام الدنيا."], "k": "«بل طبع الله عليها بكفرهم»… هل في قلبي «غلاف» يمنعني من قبول نصيحة أو حق؟"}, {"lbl": "الآيات ١٦٠ – ١٦٢", "q": "فَبِظُلۡمٖ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرٗا ﴿١٦٠﴾ وَأَخۡذِهِمُ ٱلرِّبَوٰاْ وَقَدۡ نُهُواْ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمٗا ﴿١٦١﴾ لَّـٰكِنِ ٱلرَّـٰسِخُونَ فِي ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أُوْلَـٰٓئِكَ سَنُؤۡتِيهِمۡ أَجۡرًا عَظِيمًا ﴿١٦٢﴾", "w": [["فبظلم", "الباء سببية، أي فبسبب ظلمهم."], ["هادوا", "اليهود، إذ قالوا: إنا هُدنا إليك."], ["وأخذهم الربا", "قبوله والتعامل به وأكله."], ["الراسخون في العلم", "أصحاب القدم الثابتة في معرفة الله وشرائعه، علومهم يقينيات لا ظنيات."]], "m": "ما زال السياق في كشف عظائم ذنوب اليهود: فسجّل عليهم الظلم العظيم الذي استوجبوا به أن حرّم الله عليهم طيبات كثيرة كانت حلالاً لهم، وصدّهم أنفسهم وغيرهم عن سبيل الله كثيراً بجحودهم الحق وتحريفهم كلام الله وقبولهم الرشوة في إبطال الأحكام. ثم سجّل جرائم أخرى: استباحتهم الربا وقد نُهوا عنه، وأكلهم أموال الناس بالباطل كالرشوة والفتاوى الباطلة، وأعدّ لمن مات منهم على الكفر عذاباً أليماً. ثم نزلت الآية الثالثة في عبد الله بن سلام وبعض علماء اليهود الذين آمنوا: لكن الراسخون في العلم منهم، الذين علومهم يقينية، والمؤمنون من هذه الأمة، يؤمنون بما أُنزل إليك وما أُنزل من قبلك، والمقيمين الصلاة، والمؤتون الزكاة، والمؤمنون بالله واليوم الآخر، أولئك سنؤتيهم أجراً عظيماً لا يُقدر قدره.", "h": ["المعاصي تورث الحرمان من خير الدنيا والآخرة.", "حرمة الصدّ عن الإسلام، ولو بالسلوك الشائن والمعاملة الباطلة.", "حرمة الربا، وأنه موجب للعقوبة في الدنيا والآخرة.", "حرمة أكل أموال الناس بالباطل كالسرقة والغش والرشوة.", "من أهل الكتاب صلحاء ربانيون، كعبد الله بن سلام وآخرين.", "الرسوخ في العلم يأمن صاحبه الزلّات والوقوع في المهلكات.", "فضل إقام الصلاة، لنصب «والمقيمين الصلاة» في الآية على المدح والتخصيص."], "k": "هل حرمتني معصيةٌ من خيرٍ كنت أجده: قيام ليل، أو لذة مناجاة، أو بركة رزق؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (79, 4, 163, 176, 'سورة النساء ١٦٣ – ١٧٦', 'إنا أوحينا إليك، ولا تغلوا في دينكم، وختام سورة النساء', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 79) = $j$[{"lbl": "الآيات ١٦٣ – ١٦٦", "q": "۞إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا ﴿١٦٣﴾ وَرُسُلٗا قَدۡ قَصَصۡنَٰهُمۡ عَلَيۡكَ مِن قَبۡلُ وَرُسُلٗا لَّمۡ نَقۡصُصۡهُمۡ عَلَيۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا ﴿١٦٤﴾ رُّسُلٗا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا ﴿١٦٥﴾ لَّـٰكِنِ ٱللَّهُ يَشۡهَدُ بِمَآ أَنزَلَ إِلَيۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ وَٱلۡمَلَـٰٓئِكَةُ يَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا ﴿١٦٦﴾", "w": [["إنا أوحينا إليك", "الوحي: الإعلام السريع الخفي، ووحي الله إلى أنبيائه إعلامهم بما يريد أن يعلمهم به من أمور الدين وغيره."], ["الأسباط", "أولاد يعقوب ﵈."], ["زبوراً", "أحد الكتب الإلهية، أنزله الله على نبيه داود ﵇."], ["قد قصصناهم عليك", "ورد منهم في سورة الأنعام ثمانية عشر رسولاً، وسبعة ذُكروا في سور أخرى."], ["حجة", "عذر يعتذرون به إلى ربهم عز وجل."]], "m": "رُوي أن اليهود لما سمعوا ما أنزل الله فيهم أنكروا أن يكون وحياً، وقالوا: لم يوحِ الله إلى غير موسى، فردّ الله قولهم: إنا أوحينا إليك كما أوحينا إلى نوح والنبيين من بعده، فذكر عدداً من الأنبياء، ورسلاً قد قصصنا عليك أسماءهم وبعض ما جرى لهم مع أممهم، ورسلاً لم نقصصهم عليك، وكلّم الله موسى تكليماً بلا واسطة، فكيف ينكر اليهود ذلك؟ وقد أرسلهم الله مبشّرين من آمن وعمل صالحاً بالجنة، ومنذرين من كفر وعمل سوءاً بالنار، لئلا يكون للناس على الله حجة بعد الرسل، وكان الله عزيزاً حكيماً. ثم رُوي أن يهوداً دعاهم النبي ﷺ إلى الإيمان فقالوا: من يشهد لك بالرسالة؟ فأنزل الله: لكن الله يشهد بما أنزل إليك، أنزله بعلمه، فإنزال الكتاب إليك شهادة منه لك بالرسالة، إذ حوى أعظم تشريع تعجز البشرية عن مثله، والملائكة يشهدون، وكفى بالله شهيداً.", "h": ["تقرير مبدأ الوحي الإلهي.", "أول الرسل نوح ﵇، وآخرهم محمد ﷺ.", "إثبات صفة الكلام لله تعالى.", "بيان الحكمة في إرسال الرسل، وهي قطع الحجة على الناس يوم القيامة.", "شهادة الرب تبارك وتعالى والملائكة بنبوة خاتم الأنبياء ورسالته ﷺ.", "ما حواه القرآن من تشريع ومعارف وعلوم أكبر شهادة للنبي محمد ﷺ بالنبوة والرسالة."], "k": "«وكفى بالله شهيداً»… هل يكفيني أن الله يرى عملي ولو لم يشهده أحد من الناس؟"}, {"lbl": "الآيات ١٦٧ – ١٧٠", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ قَدۡ ضَلُّواْ ضَلَٰلَۢا بَعِيدًا ﴿١٦٧﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَظَلَمُواْ لَمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ طَرِيقًا ﴿١٦٨﴾ إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا ﴿١٦٩﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُواْ خَيۡرٗا لَّكُمۡۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿١٧٠﴾", "w": [["كفروا وصدّوا عن سبيل الله", "اليهود، صدّوا بقولهم: إنا لا نجد صفة محمد في كتابنا."], ["الرسول", "محمد ﷺ، الكامل في رسالته الصادق في دعوته."], ["فآمنوا خيراً لكم", "يكون إيمانكم خيراً لكم."]], "m": "بعد أن أقام الله الحجة على رسالة نبيه ﷺ بشهادته وشهادة ملائكته وشهادة القرآن، أخبر أن الذين كفروا وصدّوا عن سبيل الله، وهم اليهود، قد ضلّوا ضلالاً بعيداً يتعذّر معه الرجوع إلى الحق، وأن الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقاً إلا طريق جهنم خالدين فيها أبداً؛ وهذه سنته: أن المرء إذا كفر كفر عناد وأضاف إلى الكفر الظلم لم يبقَ له استعداد لقبول الهداية، وكان ذلك على الله يسيراً. ثم وجّه نداءً إلى الناس كافة: قد جاءكم الرسول بالحق من ربكم، فآمنوا يكن خيراً لكم، وإن أبيتم وآثرتم الضلال فإن لله ما في السموات والأرض، وسيجزيكم بما اخترتم، وكان الله عليماً بمن استجاب ومن أعرض، حكيماً في وضع الجزاء في موضعه.", "h": ["شرّ الكفر ما كان مع الصدّ عن سبيل الله والظلم، وهذا كفر اليهود والعياذ بالله تعالى.", "سنة الله تعالى أن العبد إذا أبعد في الضلال وتوغّل في الشر والفساد يتعذّر عليه التوبة، فيموت على ذلك فيهلك.", "الرسالة المحمدية عامة لسائر الناس، أبيضهم وأصفرهم.", "إثبات صفتي العلم والحكمة لله تعالى، وبموجبهما يتم الجزاء العادل الرحيم."], "k": "هل في حياتي باب شرٍّ أتوغّل فيه شيئاً فشيئاً؟ أغلقه اليوم قبل أن يصعب الرجوع."}, {"lbl": "الآيات ١٧١ – ١٧٣", "q": "يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٞ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرٗا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهٞ وَٰحِدٞۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٞۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا ﴿١٧١﴾ لَّن يَسۡتَنكِفَ ٱلۡمَسِيحُ أَن يَكُونَ عَبۡدٗا لِّلَّهِ وَلَا ٱلۡمَلَـٰٓئِكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن يَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَيَسۡتَكۡبِرۡ فَسَيَحۡشُرُهُمۡ إِلَيۡهِ جَمِيعٗا ﴿١٧٢﴾ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ وَيَزِيدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِينَ ٱسۡتَنكَفُواْ وَٱسۡتَكۡبَرُواْ فَيُعَذِّبُهُمۡ عَذَابًا أَلِيمٗا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا ﴿١٧٣﴾", "w": [["لا تغلوا في دينكم", "الغلو: مجاوزة الحد بالتنطّع والتكلّف."], ["المسيح", "عيسى ﵇، لُقّب بالمسيح لأنه ممسوح من الذنوب، أي لا ذنب له قط."], ["وكلمته ألقاها إلى مريم", "قول الله له «كن» فكان، وألقاها إلى مريم: أوصلها إليها بقول الملائكة: إن الله يبشّرك بكلمة منه اسمه المسيح."], ["وروح منه", "كان عيسى بنفخة جبريل، روح الله، في كمّ درعها."], ["وكيلاً", "حفيظاً وشاهداً عليماً."], ["لن يستنكف", "لن يرفض عبوديته لله أنفةً وكبراً."], ["ويستكبر", "يرى نفسه كبيرة فوق ما طُلب منه، إعجاباً وغروراً."], ["ولياً ولا نصيراً", "لا يجدون يوم القيامة ولياً يتولّى الدفاع عنهم، ولا نصيراً ينصرهم."]], "m": "ما زال السياق مع أهل الكتاب، فنادى الله النصارى ونهاهم عن الغلو في دينهم بالتنطّع والتكلّف كالترهّب واعتزال النساء وما إلى ذلك من البدع، ونهاهم أن يقولوا على الله غير الحق بنسبة الولد إليه. وأخبرهم أن عيسى لم يكن إلا رسول الله وكلمته التي ألقاها إلى مريم، إذ بعث إليها جبريل فبشّرها بغلام زكي، ونفخ في كمّ درعها، فكان عيسى بكلمة التكوين «كن» وبتلك النفخة، فلم يكن الله ولا ابن الله؛ فآمنوا بالله ورسله، ولا تقولوا: ثلاثة، انتهوا يكن خيراً لكم، إنما الله إله واحد، سبحانه أن يكون له ولد، له ما في السموات وما في الأرض، وكفى بالله وكيلاً. ثم أخبر أن المسيح لن يستنكف أن يكون عبداً لله، ولا الملائكة المقربون، ومن يستنكف عن عبادته ويستكبر فسيحشرهم إليه جميعاً: فأما الذين آمنوا وعملوا الصالحات فيوفّيهم أجورهم ويزيدهم من فضله، الحسنة بعشر أمثالها إلى سبعمائة ضعف، وأما الذين استنكفوا واستكبروا فيعذّبهم عذاباً أليماً، ولا يجدون لهم من دون الله ولياً ولا نصيراً.", "h": ["حرمة الغلو في الدين، إذ هو من الأسباب الموجبة للابتداع والضلال.", "حرمة القول على الله تعالى بدون علم مطلقاً، والقول عليه بغير الحق بصورة خاصة.", "بيان المعتقد الحق في عيسى ﵇، وأنه عبد الله ورسوله، كان بكلمة الله ونفخة جبريل.", "حرمة الاستنكاف عن الحق والاستكبار عن قبوله.", "بيان الجزاء الأخروي، وهو إما نعيم وإما جحيم."], "k": "«لن يستنكف المسيح أن يكون عبداً لله»… هل أفرح بأنني عبدٌ لله، وأعدّها أعظم ألقابي؟"}, {"lbl": "الآيتان ١٧٤ – ١٧٥", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُم بُرۡهَٰنٞ مِّن رَّبِّكُمۡ وَأَنزَلۡنَآ إِلَيۡكُمۡ نُورٗا مُّبِينٗا ﴿١٧٤﴾ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَٱعۡتَصَمُواْ بِهِۦ فَسَيُدۡخِلُهُمۡ فِي رَحۡمَةٖ مِّنۡهُ وَفَضۡلٖ وَيَهۡدِيهِمۡ إِلَيۡهِ صِرَٰطٗا مُّسۡتَقِيمٗا ﴿١٧٥﴾", "w": [["برهان", "الحجة، والمراد به هنا محمد ﷺ."], ["نوراً مبيناً", "القرآن الكريم."], ["واعتصموا به", "تمسّكوا بالقرآن وبما يحمله من الشرائع."], ["في رحمة منه", "الجنة."], ["صراطاً", "طريقاً يفضي بهم إلى جوار ربهم في دار الكرامة."]], "m": "ينادي الله سائر الناس، مشركين ويهوداً ونصارى، قاطعاً الحجة عليهم بأنه أرسل إليهم رسوله محمداً ﷺ، البرهان الساطع على وجود الله وعلمه وقدرته ووجوب الإيمان به، وأنزل عليه كتابه نوراً مبيناً يهدي به من اتبع رضوانه سبل السلام، وبهذا أعذر الله إلى الناس كافة. ثم هم صنفان: فالذين آمنوا بالله رباً وإلهاً وبرسوله نبياً، واعتصموا بالقرآن فأحلّوا حلاله وحرّموا حرامه وصدّقوا أنباءه والتزموا آدابه، فسيدخلهم في رحمة منه وفضل، فينجيهم من النار ويدخلهم الجنة، ويهديهم إليه صراطاً مستقيماً. وأما الذين كفروا فمصيرهم معروف لا حاجة إلى ذكره: الحرمان والخسران.", "h": ["الدعوة الإسلامية دعوة عامة، فهي للأبيض والأصفر على حد سواء.", "إطلاق لفظ البرهان على النبي محمد ﷺ، لأنه بأمّيته وكماله الذي لا مطمع لبشر أن يساميه فيه برهان على وجود الله وعلمه ورحمته.", "القرآن نور، لما يحصل به من الاهتداء إلى سبيل النجاة وطرق السعادة والكمال.", "ثمن السعادة ودخول الجنة: الإيمان بالله ورسوله ولقائه، والعمل الصالح، وهو التمسك بالكتاب والسنة، المعبّر عنه بالاعتصام."], "k": "«واعتصموا به»… بماذا أتمسّك حين تشتدّ الفتن حولي؟"}, {"lbl": "الآية ١٧٦", "q": "يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ لَيۡسَ لَهُۥ وَلَدٞ وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ إِن لَّمۡ يَكُن لَّهَا وَلَدٞۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ ﴿١٧٦﴾", "w": [["يستفتونك", "يطلبون فتياك في كذا."], ["يفتيكم", "يبيّن لكم ما أشكل عليكم من أمر الكلالة."], ["الكلالة", "أن يهلك الرجل ولا يترك ولداً ولا ولد ولد، وإنما يترك أخاً أو أختاً."], ["أن تضلّوا", "كيلا تضلّوا، أي تخطئوا في قسمة التركة."]], "m": "هذه آية الكلالة، وآيات المواريث أربع: الأولى في شأن الولد والوالد، والثانية في شأن الزوجين والإخوة لأم، وقد تقدّمتا في أول السورة، والثالثة هذه في ميراث الإخوة والأخوات عند موت أحدهم ولم يترك ولداً ولا ولد ولد، والرابعة في آخر سورة الأنفال في شأن ذوي الأرحام. نزلت عند سؤال بعض الصحابة عن الكلالة، فقال تعالى: قل الله يفتيكم في الكلالة: إن هلك امرؤ ليس له ولد ولا ولد ولد، وله أخت شقيقة أو لأب، فلها نصف ما ترك، وهو يرثها إن لم يكن لها ولد، فإن كانتا اثنتين فلهما الثلثان مما ترك، وإن كانوا إخوة رجالاً ونساءً فللذكر مثل حظ الأنثيين. يبيّن الله لكم كيلا تضلّوا في قسمة التركات فتخطئوا الحق وتجوروا، والله بكل شيء عليم.", "h": ["جواز سؤال من لا يعلم من يعلم، للحصول على العلم المطلوب له.", "إثبات وجود الله تعالى عليماً قديراً سميعاً بصيراً، وتقرير نبوة محمد ﷺ؛ إذ سؤال الأصحاب وإجابة الرب بوحيه المنزل على رسوله يقرّر ذلك.", "بيان قسمة تركة من يُورث كلالة: فالأخت الواحدة لها من أخيها نصف ما ترك، والأختان لهما الثلثان، والإخوة مع الأخوات للذكر مثل حظ الأنثيين، والأخ يرث أخته إن لم يكن لها ولد ولا ولد ولد."], "k": "«يبيّن الله لكم أن تضلّوا»… هل أسأل أهل العلم عما أجهله من ديني، أم أكتفي بالظن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 79;
insert into public.tdb_cards(topic, i, body) select 79, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٦٣ – ١٦٦", "q": "۞إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا ﴿١٦٣﴾ وَرُسُلٗا قَدۡ قَصَصۡنَٰهُمۡ عَلَيۡكَ مِن قَبۡلُ وَرُسُلٗا لَّمۡ نَقۡصُصۡهُمۡ عَلَيۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا ﴿١٦٤﴾ رُّسُلٗا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا ﴿١٦٥﴾ لَّـٰكِنِ ٱللَّهُ يَشۡهَدُ بِمَآ أَنزَلَ إِلَيۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ وَٱلۡمَلَـٰٓئِكَةُ يَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا ﴿١٦٦﴾", "w": [["إنا أوحينا إليك", "الوحي: الإعلام السريع الخفي، ووحي الله إلى أنبيائه إعلامهم بما يريد أن يعلمهم به من أمور الدين وغيره."], ["الأسباط", "أولاد يعقوب ﵈."], ["زبوراً", "أحد الكتب الإلهية، أنزله الله على نبيه داود ﵇."], ["قد قصصناهم عليك", "ورد منهم في سورة الأنعام ثمانية عشر رسولاً، وسبعة ذُكروا في سور أخرى."], ["حجة", "عذر يعتذرون به إلى ربهم عز وجل."]], "m": "رُوي أن اليهود لما سمعوا ما أنزل الله فيهم أنكروا أن يكون وحياً، وقالوا: لم يوحِ الله إلى غير موسى، فردّ الله قولهم: إنا أوحينا إليك كما أوحينا إلى نوح والنبيين من بعده، فذكر عدداً من الأنبياء، ورسلاً قد قصصنا عليك أسماءهم وبعض ما جرى لهم مع أممهم، ورسلاً لم نقصصهم عليك، وكلّم الله موسى تكليماً بلا واسطة، فكيف ينكر اليهود ذلك؟ وقد أرسلهم الله مبشّرين من آمن وعمل صالحاً بالجنة، ومنذرين من كفر وعمل سوءاً بالنار، لئلا يكون للناس على الله حجة بعد الرسل، وكان الله عزيزاً حكيماً. ثم رُوي أن يهوداً دعاهم النبي ﷺ إلى الإيمان فقالوا: من يشهد لك بالرسالة؟ فأنزل الله: لكن الله يشهد بما أنزل إليك، أنزله بعلمه، فإنزال الكتاب إليك شهادة منه لك بالرسالة، إذ حوى أعظم تشريع تعجز البشرية عن مثله، والملائكة يشهدون، وكفى بالله شهيداً.", "h": ["تقرير مبدأ الوحي الإلهي.", "أول الرسل نوح ﵇، وآخرهم محمد ﷺ.", "إثبات صفة الكلام لله تعالى.", "بيان الحكمة في إرسال الرسل، وهي قطع الحجة على الناس يوم القيامة.", "شهادة الرب تبارك وتعالى والملائكة بنبوة خاتم الأنبياء ورسالته ﷺ.", "ما حواه القرآن من تشريع ومعارف وعلوم أكبر شهادة للنبي محمد ﷺ بالنبوة والرسالة."], "k": "«وكفى بالله شهيداً»… هل يكفيني أن الله يرى عملي ولو لم يشهده أحد من الناس؟"}, {"lbl": "الآيات ١٦٧ – ١٧٠", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ قَدۡ ضَلُّواْ ضَلَٰلَۢا بَعِيدًا ﴿١٦٧﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَظَلَمُواْ لَمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ طَرِيقًا ﴿١٦٨﴾ إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا ﴿١٦٩﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُواْ خَيۡرٗا لَّكُمۡۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿١٧٠﴾", "w": [["كفروا وصدّوا عن سبيل الله", "اليهود، صدّوا بقولهم: إنا لا نجد صفة محمد في كتابنا."], ["الرسول", "محمد ﷺ، الكامل في رسالته الصادق في دعوته."], ["فآمنوا خيراً لكم", "يكون إيمانكم خيراً لكم."]], "m": "بعد أن أقام الله الحجة على رسالة نبيه ﷺ بشهادته وشهادة ملائكته وشهادة القرآن، أخبر أن الذين كفروا وصدّوا عن سبيل الله، وهم اليهود، قد ضلّوا ضلالاً بعيداً يتعذّر معه الرجوع إلى الحق، وأن الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقاً إلا طريق جهنم خالدين فيها أبداً؛ وهذه سنته: أن المرء إذا كفر كفر عناد وأضاف إلى الكفر الظلم لم يبقَ له استعداد لقبول الهداية، وكان ذلك على الله يسيراً. ثم وجّه نداءً إلى الناس كافة: قد جاءكم الرسول بالحق من ربكم، فآمنوا يكن خيراً لكم، وإن أبيتم وآثرتم الضلال فإن لله ما في السموات والأرض، وسيجزيكم بما اخترتم، وكان الله عليماً بمن استجاب ومن أعرض، حكيماً في وضع الجزاء في موضعه.", "h": ["شرّ الكفر ما كان مع الصدّ عن سبيل الله والظلم، وهذا كفر اليهود والعياذ بالله تعالى.", "سنة الله تعالى أن العبد إذا أبعد في الضلال وتوغّل في الشر والفساد يتعذّر عليه التوبة، فيموت على ذلك فيهلك.", "الرسالة المحمدية عامة لسائر الناس، أبيضهم وأصفرهم.", "إثبات صفتي العلم والحكمة لله تعالى، وبموجبهما يتم الجزاء العادل الرحيم."], "k": "هل في حياتي باب شرٍّ أتوغّل فيه شيئاً فشيئاً؟ أغلقه اليوم قبل أن يصعب الرجوع."}, {"lbl": "الآيات ١٧١ – ١٧٣", "q": "يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٞ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرٗا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهٞ وَٰحِدٞۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٞۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا ﴿١٧١﴾ لَّن يَسۡتَنكِفَ ٱلۡمَسِيحُ أَن يَكُونَ عَبۡدٗا لِّلَّهِ وَلَا ٱلۡمَلَـٰٓئِكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن يَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَيَسۡتَكۡبِرۡ فَسَيَحۡشُرُهُمۡ إِلَيۡهِ جَمِيعٗا ﴿١٧٢﴾ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ وَيَزِيدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِينَ ٱسۡتَنكَفُواْ وَٱسۡتَكۡبَرُواْ فَيُعَذِّبُهُمۡ عَذَابًا أَلِيمٗا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا ﴿١٧٣﴾", "w": [["لا تغلوا في دينكم", "الغلو: مجاوزة الحد بالتنطّع والتكلّف."], ["المسيح", "عيسى ﵇، لُقّب بالمسيح لأنه ممسوح من الذنوب، أي لا ذنب له قط."], ["وكلمته ألقاها إلى مريم", "قول الله له «كن» فكان، وألقاها إلى مريم: أوصلها إليها بقول الملائكة: إن الله يبشّرك بكلمة منه اسمه المسيح."], ["وروح منه", "كان عيسى بنفخة جبريل، روح الله، في كمّ درعها."], ["وكيلاً", "حفيظاً وشاهداً عليماً."], ["لن يستنكف", "لن يرفض عبوديته لله أنفةً وكبراً."], ["ويستكبر", "يرى نفسه كبيرة فوق ما طُلب منه، إعجاباً وغروراً."], ["ولياً ولا نصيراً", "لا يجدون يوم القيامة ولياً يتولّى الدفاع عنهم، ولا نصيراً ينصرهم."]], "m": "ما زال السياق مع أهل الكتاب، فنادى الله النصارى ونهاهم عن الغلو في دينهم بالتنطّع والتكلّف كالترهّب واعتزال النساء وما إلى ذلك من البدع، ونهاهم أن يقولوا على الله غير الحق بنسبة الولد إليه. وأخبرهم أن عيسى لم يكن إلا رسول الله وكلمته التي ألقاها إلى مريم، إذ بعث إليها جبريل فبشّرها بغلام زكي، ونفخ في كمّ درعها، فكان عيسى بكلمة التكوين «كن» وبتلك النفخة، فلم يكن الله ولا ابن الله؛ فآمنوا بالله ورسله، ولا تقولوا: ثلاثة، انتهوا يكن خيراً لكم، إنما الله إله واحد، سبحانه أن يكون له ولد، له ما في السموات وما في الأرض، وكفى بالله وكيلاً. ثم أخبر أن المسيح لن يستنكف أن يكون عبداً لله، ولا الملائكة المقربون، ومن يستنكف عن عبادته ويستكبر فسيحشرهم إليه جميعاً: فأما الذين آمنوا وعملوا الصالحات فيوفّيهم أجورهم ويزيدهم من فضله، الحسنة بعشر أمثالها إلى سبعمائة ضعف، وأما الذين استنكفوا واستكبروا فيعذّبهم عذاباً أليماً، ولا يجدون لهم من دون الله ولياً ولا نصيراً.", "h": ["حرمة الغلو في الدين، إذ هو من الأسباب الموجبة للابتداع والضلال.", "حرمة القول على الله تعالى بدون علم مطلقاً، والقول عليه بغير الحق بصورة خاصة.", "بيان المعتقد الحق في عيسى ﵇، وأنه عبد الله ورسوله، كان بكلمة الله ونفخة جبريل.", "حرمة الاستنكاف عن الحق والاستكبار عن قبوله.", "بيان الجزاء الأخروي، وهو إما نعيم وإما جحيم."], "k": "«لن يستنكف المسيح أن يكون عبداً لله»… هل أفرح بأنني عبدٌ لله، وأعدّها أعظم ألقابي؟"}, {"lbl": "الآيتان ١٧٤ – ١٧٥", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُم بُرۡهَٰنٞ مِّن رَّبِّكُمۡ وَأَنزَلۡنَآ إِلَيۡكُمۡ نُورٗا مُّبِينٗا ﴿١٧٤﴾ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَٱعۡتَصَمُواْ بِهِۦ فَسَيُدۡخِلُهُمۡ فِي رَحۡمَةٖ مِّنۡهُ وَفَضۡلٖ وَيَهۡدِيهِمۡ إِلَيۡهِ صِرَٰطٗا مُّسۡتَقِيمٗا ﴿١٧٥﴾", "w": [["برهان", "الحجة، والمراد به هنا محمد ﷺ."], ["نوراً مبيناً", "القرآن الكريم."], ["واعتصموا به", "تمسّكوا بالقرآن وبما يحمله من الشرائع."], ["في رحمة منه", "الجنة."], ["صراطاً", "طريقاً يفضي بهم إلى جوار ربهم في دار الكرامة."]], "m": "ينادي الله سائر الناس، مشركين ويهوداً ونصارى، قاطعاً الحجة عليهم بأنه أرسل إليهم رسوله محمداً ﷺ، البرهان الساطع على وجود الله وعلمه وقدرته ووجوب الإيمان به، وأنزل عليه كتابه نوراً مبيناً يهدي به من اتبع رضوانه سبل السلام، وبهذا أعذر الله إلى الناس كافة. ثم هم صنفان: فالذين آمنوا بالله رباً وإلهاً وبرسوله نبياً، واعتصموا بالقرآن فأحلّوا حلاله وحرّموا حرامه وصدّقوا أنباءه والتزموا آدابه، فسيدخلهم في رحمة منه وفضل، فينجيهم من النار ويدخلهم الجنة، ويهديهم إليه صراطاً مستقيماً. وأما الذين كفروا فمصيرهم معروف لا حاجة إلى ذكره: الحرمان والخسران.", "h": ["الدعوة الإسلامية دعوة عامة، فهي للأبيض والأصفر على حد سواء.", "إطلاق لفظ البرهان على النبي محمد ﷺ، لأنه بأمّيته وكماله الذي لا مطمع لبشر أن يساميه فيه برهان على وجود الله وعلمه ورحمته.", "القرآن نور، لما يحصل به من الاهتداء إلى سبيل النجاة وطرق السعادة والكمال.", "ثمن السعادة ودخول الجنة: الإيمان بالله ورسوله ولقائه، والعمل الصالح، وهو التمسك بالكتاب والسنة، المعبّر عنه بالاعتصام."], "k": "«واعتصموا به»… بماذا أتمسّك حين تشتدّ الفتن حولي؟"}, {"lbl": "الآية ١٧٦", "q": "يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ لَيۡسَ لَهُۥ وَلَدٞ وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ إِن لَّمۡ يَكُن لَّهَا وَلَدٞۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ ﴿١٧٦﴾", "w": [["يستفتونك", "يطلبون فتياك في كذا."], ["يفتيكم", "يبيّن لكم ما أشكل عليكم من أمر الكلالة."], ["الكلالة", "أن يهلك الرجل ولا يترك ولداً ولا ولد ولد، وإنما يترك أخاً أو أختاً."], ["أن تضلّوا", "كيلا تضلّوا، أي تخطئوا في قسمة التركة."]], "m": "هذه آية الكلالة، وآيات المواريث أربع: الأولى في شأن الولد والوالد، والثانية في شأن الزوجين والإخوة لأم، وقد تقدّمتا في أول السورة، والثالثة هذه في ميراث الإخوة والأخوات عند موت أحدهم ولم يترك ولداً ولا ولد ولد، والرابعة في آخر سورة الأنفال في شأن ذوي الأرحام. نزلت عند سؤال بعض الصحابة عن الكلالة، فقال تعالى: قل الله يفتيكم في الكلالة: إن هلك امرؤ ليس له ولد ولا ولد ولد، وله أخت شقيقة أو لأب، فلها نصف ما ترك، وهو يرثها إن لم يكن لها ولد، فإن كانتا اثنتين فلهما الثلثان مما ترك، وإن كانوا إخوة رجالاً ونساءً فللذكر مثل حظ الأنثيين. يبيّن الله لكم كيلا تضلّوا في قسمة التركات فتخطئوا الحق وتجوروا، والله بكل شيء عليم.", "h": ["جواز سؤال من لا يعلم من يعلم، للحصول على العلم المطلوب له.", "إثبات وجود الله تعالى عليماً قديراً سميعاً بصيراً، وتقرير نبوة محمد ﷺ؛ إذ سؤال الأصحاب وإجابة الرب بوحيه المنزل على رسوله يقرّر ذلك.", "بيان قسمة تركة من يُورث كلالة: فالأخت الواحدة لها من أخيها نصف ما ترك، والأختان لهما الثلثان، والإخوة مع الأخوات للذكر مثل حظ الأنثيين، والأخ يرث أخته إن لم يكن لها ولد ولا ولد ولد."], "k": "«يبيّن الله لكم أن تضلّوا»… هل أسأل أهل العلم عما أجهله من ديني، أم أكتفي بالظن؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (80, 5, 1, 7, 'سورة المائدة ١ – ٧', 'افتتاح سورة المائدة: أوفوا بالعقود، والمحرّمات من الطعام، والطهارة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 80) = $j$[{"lbl": "الآيتان ١ – ٢", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ ٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ ﴿١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَـٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَـٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٢﴾", "w": [["أوفوا بالعقود", "العقود: العهود التي بين العبد وربه، وبين العبد وأخيه، والوفاء بها: عدم نكثها والإخلال بمقتضاها."], ["وأنتم حُرُم", "محرمون بحج أو عمرة."], ["شعائر الله", "جمع شعيرة، وهي هنا مناسك الحج والعمرة، وسائر أعلام دين الله."], ["الشهر الحرام", "رجب، شهر مضر الذي كانت تعظّمه."], ["الهدي", "ما يُهدى للبيت والحرم من بهيمة الأنعام."], ["القلائد", "جمع قلادة، ما يُقلّد به الهدي، وما يتقلّده الرجل من لحاء شجر الحرم ليأمن."], ["آمّين البيت الحرام", "قاصديه يطلبون ربح تجارة أو رضوان الله."], ["وإذا حللتم", "من إحرامكم."], ["أن صدّوكم", "لأجل أن صدّوكم."], ["البر والتقوى", "البر: كل طاعة لله ورسوله، والتقوى: فعل ما أمر الله به ورسوله وترك ما نهيا عنه."], ["الإثم والعدوان", "الإثم: سائر الذنوب، والعدوان: الظلم وتجاوز الحدود."], ["شديد العقاب", "عقابه شديد لا يُطاق."]], "m": "ينادي الله عباده المؤمنين: أوفوا بالعقود فلا تحلّوها، وبالعهود فلا تنكثوها، فلا تتركوا واجباً ولا ترتكبوا منهياً، ولا تحرّموا حلالاً ولا تحلّوا حراماً: أُحلّت لكم بهيمة الأنعام، الإبل والبقر والغنم، إلا ما يُتلى عليكم في الآية التالية، غير محلّي الصيد وأنتم محرمون، إن الله يحكم ما يريد فسلّموا له. ثم نهاهم عن إحلال شعائر الله بترك واجب أو فعل محرّم، ومن ذلك مناسك الحج والعمرة. ومن المنسوخ في الآية تحريم القتال في الشهر الحرام، وهدي المشركين وقلائدهم، فلا يُسمح لهم بدخول الحرم. وإذا تحلّلتم من إحرامكم فاصطادوا. ولا يحملنّكم بغض قوم صدّوكم يوم الحديبية عن المسجد الحرام أن تعتدوا عليهم بغير ما أذن الله. وتعاونوا على البر والتقوى، أي على أداء الواجبات والفضائل وترك المحرّمات والرذائل، ولا تعاونوا على الإثم والعدوان، واتقوا الله إن الله شديد العقاب.", "h": ["وجوب الوفاء بالعهود التي بين الله تعالى وبين العبد، والمحافظة على العقود التي بين العبد وأخيه؛ لشمول الآية ذلك.", "إباحة أكل لحوم الإبل والبقر والغنم إلا الميتة منها.", "تحريم الصيد في حال الإحرام وحلّيته بعد التحلّل، وهو صيد البر لا البحر.", "وجوب احترام شعائر الدين كلها، أداءً لما وجب أداؤه وتركاً لما وجب تركه.", "حرمة الاعتداء مطلقاً، حتى على الكافر.", "وجوب التعاون بين المؤمنين على إقامة الدين، وحرمة تعاونهم على المساس به."], "k": "«وتعاونوا على البر والتقوى»… من أتعاون معه اليوم على خير؟ وهل أعين أحداً على إثم ولو بكلمة؟"}, {"lbl": "الآية ٣", "q": "حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٣﴾", "w": [["وما أُهلّ لغير الله به", "ما ذُكر عليه اسم غير اسم الله، كاسم المسيح أو الولي."], ["المنخنقة", "التي خُنقت بحبل ونحوه فماتت."], ["الموقوذة", "المضروبة بعصا أو حجر فماتت."], ["المتردّية", "الساقطة من علٍ إلى أسفل فماتت."], ["النطيحة", "ما ماتت بسبب نطح أختها لها."], ["وما أكل السبع", "ما أكل منه الذئب وغيره من المفترسات."], ["إلا ما ذكّيتم", "ما أدركتم فيه الروح مستقرة فذكّيتموه بذبح أو نحر."], ["وما ذُبح على النُّصُب", "ما ذُبح على الأصنام المنصوبة، ومثلها ما ذُبح على أضرحة الأولياء وقبورهم."], ["وأن تستقسموا بالأزلام", "طلب معرفة ما قُسم من خير أو شر بالقداح، ومثله الكهانة وما يشبهها."], ["ذلكم فسق", "خروج عن طاعة الله ومعصية له."], ["فمن اضطُرّ", "من ألجأته ضرورة الجوع فخاف على نفسه الموت."], ["في مخمصة", "المخمصة: شدة الجوع حتى يضمر البطن."], ["غير متجانف لإثم", "غير مائل إلى المعصية، بأن يأكل قدر ما يسدّ رمقه ويدفع غائلة الجوع المهلك."]], "m": "هذه الآية تفصيل لقوله في أول السورة: «إلا ما يُتلى عليكم»، فذكر المحرّمات من اللحوم: الميتة، والدم، ولحم الخنزير، وما أُهلّ لغير الله به، والمنخنقة، والموقوذة، والمتردّية، والنطيحة، وما أكل السبع، إلا ما أدركتم فيه الروح مستقرة فذكّيتموه، وما ذُبح على النصب. وحرّم الاستقسام بالأزلام، وكانوا في الجاهلية يكتبون على قدح «أمرني ربي» وعلى آخر «نهاني ربي»، فيُجيلها المستقسم ويُخرج أحدها فيمضي أو يترك، فحرّمه الإسلام، وسنّ الاستخارة: ركعتين من غير الفريضة ثم الدعاء المعروف. ذلكم فسق. ثم أخبر أن الكافرين يئسوا اليوم من أن يردّوكم عن دينكم، بعد فتح مكة ودخول ثقيف وهوازن في الإسلام، فلا تخشوهم واخشوني بطاعتي ولزوم حدودي. اليوم أكملت لكم دينكم بجميع عقائده وعباداته وأحكامه وآدابه، وقد نزلت عشية عرفة في حجة الوداع، ولم يعش بعدها رسول الله ﷺ إلا إحدى وثمانين ليلة، وأتممت عليكم نعمتي فأمّنتكم بعد خوف وأعززتكم بعد ذل وهديتكم بعد ضلال، ورضيت لكم الإسلام ديناً. ثم رخّص لمن اضطرّه الجوع الشديد أن يأكل مما حرّم غير مائل إلى الإثم، فإن الله غفور رحيم.", "h": ["حرمة الميتة وما ذُكر معها، وهي عشر من المحرمات.", "حرمة الاستقسام بالأزلام، ومثلها قرعة الأنبياء وخط الرمل والكهانة وما أشبه ذلك.", "حرمة الذبح على القبور والقباب والنصب التذكارية، وهي من الشرك.", "جواز أكل ما أدركه المسلم حياً من الحيوان المأكول فذكّاه، وإن كان قد جُرح أو كُسر أو أشرف على الموت بأي سبب مميت.", "وجوب خشية الله تعالى، وحرمة خشية الكفار.", "حرمة الابتداع في الدين، وحرمة التشريع المنافي للشرع الإسلامي.", "جواز أكل الميتة لمن اضطُرّ من شدة الجوع فخاف على نفسه الهلاك، بشرط ألا يكون قاصداً المعصية مائلاً إلى الإثم."], "k": "«اليوم أكملت لكم دينكم»… الدين كامل، فهل أستغني به عن البدع، وأستخير الله بدل التطيّر والحظ؟"}, {"lbl": "الآيتان ٤ – ٥", "q": "يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿٤﴾ ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلّٞ لَّكُمۡ وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانٖۗ وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ ﴿٥﴾", "w": [["الطيبات", "ما أذن الله في أكله وأباحه لعباده المؤمنين."], ["مكلّبين", "مرسلين الجارحة على الصيد، كلباً كانت أو غيره."], ["طعام الذين أوتوا الكتاب", "ذبائح اليهود والنصارى."], ["المحصنات", "جمع محصنة، وهي العفيفة الحرة من النساء."], ["أجورهن", "مهورهن وصدقاتهن."], ["غير مسافحين", "غير مجاهرين بالزنى."], ["أخدان", "جمع خِدن، وهو الخليل والصاحب السرّي."], ["ومن يكفر بالإيمان", "يرتدّ عن الإيمان."], ["حبط عمله", "بطل كل ما قدّمه من الصالحات فلا يُثاب عليه."]], "m": "لما سأل بعض الصحابة عما يحل لهم، أنزل الله: يسألونك ماذا أُحلّ لهم؟ قل أُحلّ لكم الطيبات، وهي كل ما لذّ وطاب مما أباحه الله، وصيد ما علّمتم من الجوارح، كالكلاب والفهود والصقور، مرسلين لها على الصيد، تؤدّبونها بما علّمكم الله، وحدّ الجارحة المعلّمة: إذا أُرسلت ذهبت، وإذا زُجرت انزجرت، وإذا دُعيت أجابت. فكلوا مما أمسكن عليكم، واذكروا اسم الله عليه عند إرسالها، بشرط ألا تأكل منه، فإن أكلت فقد أمسكت لنفسها، إلا إن أُدرك حياً فذُكّي. واتقوا الله إن الله سريع الحساب. ثم قال: اليوم أُحلّ لكم الطيبات، وطعام الذين أوتوا الكتاب، أي ذبائح اليهود والنصارى، حلّ لكم، وطعامكم حلّ لهم، وأُحلّ لكم نكاح المحصنات العفائف من المؤمنات ومن الكتابيات، إذا آتيتموهن مهورهن، بعقد شرعي تام الشروط، لا مسافحين ولا متخذي أخدان سراً. ومن يكفر بعد إيمانه فقد حبط عمله، وهو في الآخرة من الخاسرين، وفيه إشارة إلى أن استباحة المحرّمات قد تؤدي إلى الكفر.", "h": ["مشروعية سؤال من لا يعلم عما ينبغي له أن يعلمه.", "حلّية الصيد إن توفّرت شروطه: أن يكون الجارح معلّماً، وأن يُذكر اسم الله عند إرساله، وألا يأكل منه، ويجوز أكل ما صيد برصاص أو آلة حادّة بشرط ذكر اسم الله عند رميه.", "إباحة طعام وذبائح أهل الكتاب.", "إباحة نكاح الكتابيات بشرط أن تكون حرة عفيفة، وأن يُعقد عليها العقد الشرعي القائم على الولي والشهود والمهر والصيغة.", "حرمة نكاح المتعة ونكاح الخلّة والصحبة الخاصة.", "المعاصي قد تقود إلى الكفر.", "المرتد عن الإسلام يحبط عمله، فلو راجع الإسلام لا يُثاب على ما فعله قبل الردة، وإن مات قبل العودة خسر نفسه وأهله يوم القيامة."], "k": "«قل أُحلّ لكم الطيبات»… الحلال واسع، فلماذا أتطلّع أحياناً إلى ما حرّم الله؟"}, {"lbl": "الآيتان ٦ – ٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٦﴾ وَٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ وَمِيثَٰقَهُ ٱلَّذِي وَاثَقَكُم بِهِۦٓ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٧﴾", "w": [["إذا قمتم إلى الصلاة", "إذا أردتم القيام إليها وأنتم على غير وضوء."], ["فاغسلوا وجوهكم", "بعد غسل الكفين ثلاثاً والمضمضة والاستنشاق والاستنثار، لبيان رسول الله ﷺ ذلك."], ["وأرجلكم إلى الكعبين", "واغسلوا أرجلكم إلى الكعبين، إلا أن يكون عليها خفّ ساتر لُبس بعد وضوء، فيُمسح عليه يوماً وليلة للمقيم، وثلاثة أيام للمسافر، بهذا جاءت السنة."], ["وإن كنتم جُنُباً", "الجنب: من قامت به جنابة، بالجماع أو خروج المني بلذة في نوم أو يقظة."], ["فاطّهّروا", "فاغتسلوا، والغسل: غسل سائر الجسد بالماء."], ["الغائط", "كناية عن الخارج من أحد السبيلين."], ["أو لامستم النساء", "كناية عن الجماع، ومن لامس امرأة ليتلذّذ بها انتقض وضوؤه."], ["فتيمّموا صعيداً", "اقصدوا تراباً أو حجراً أو رملاً أو سبخة مما صعد على وجه الأرض."], ["ميثاقه", "عهده المؤكد، والمراد شهادة أن لا إله إلا الله وأن محمداً رسول الله، إذ بها وجب الالتزام بسائر التكاليف."]], "m": "نادى الله عباده المؤمنين يأمرهم بالطهارة إذا أرادوا الصلاة، وهي مناجاة العبد لربه، فبيّن الطهارة الصغرى وهي الوضوء، والكبرى وهي الغسل، وما ينوب عنهما عند العجز وهو التيمم: فاغسلوا وجوهكم، وحدّ الوجه طولاً من منبت الشعر إلى منتهى الذقن، وعرضاً من الأذن إلى الأذن، وأيديكم إلى المرافق فيدخل المرفقان، وامسحوا برؤوسكم، والسنة بيّنت أن يُقبل بيديه ويُدبر فيمسح جميع رأسه ثم أذنيه، وأرجلكم إلى الكعبين، وبيّنت السنة المسح على الخفين، والترتيب، والموالاة، والنية، والتسمية. وإن كنتم جنباً فاغتسلوا، وانقطاع دم الحيض والنفاس كالجنابة. وإن كنتم مرضى يضرّكم الماء، أو على سفر، أو جاء أحد منكم من الغائط، أو لامستم النساء، فلم تجدوا ماء، فتيمّموا صعيداً طيباً طاهراً، فاضربوا بالكفين الأرض وامسحوا الوجه والكفين مرة واحدة. ما يريد الله ليجعل عليكم من حرج، ولكن يريد ليطهّركم من الأحداث والذنوب، إذ الوضوء كفّارة للذنوب، وليتمّ نعمته عليكم لعلكم تشكرون. ثم أمرهم أن يذكروا نعمته عليهم بالهداية، وميثاقه الذي واثقهم به إذ قالوا: سمعنا وأطعنا، قالها الصحابة حين بايعوا رسول الله ﷺ، وقالها كل مسلم بلسان الحال لما شهد الشهادتين، واتقوا الله إن الله عليم بذات الصدور.", "h": ["الأمر بالطهارة، وبيان كيفية الوضوء، وكيفية الغسل، وكيفية التيمم.", "بيان الأعذار الناقلة للمؤمن من الوضوء إلى التيمم.", "بيان موجبات الوضوء والغسل.", "الشكر هو علة الإنعام.", "ذكر العهود يساعد على التزامها والمحافظة عليها."], "k": "«ولكن يريد ليطهّركم»… هل أستحضر في وضوئي القادم أنه يطهّرني من ذنوبي أيضاً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 80;
insert into public.tdb_cards(topic, i, body) select 80, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١ – ٢", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ ٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ ﴿١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَـٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَـٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٢﴾", "w": [["أوفوا بالعقود", "العقود: العهود التي بين العبد وربه، وبين العبد وأخيه، والوفاء بها: عدم نكثها والإخلال بمقتضاها."], ["وأنتم حُرُم", "محرمون بحج أو عمرة."], ["شعائر الله", "جمع شعيرة، وهي هنا مناسك الحج والعمرة، وسائر أعلام دين الله."], ["الشهر الحرام", "رجب، شهر مضر الذي كانت تعظّمه."], ["الهدي", "ما يُهدى للبيت والحرم من بهيمة الأنعام."], ["القلائد", "جمع قلادة، ما يُقلّد به الهدي، وما يتقلّده الرجل من لحاء شجر الحرم ليأمن."], ["آمّين البيت الحرام", "قاصديه يطلبون ربح تجارة أو رضوان الله."], ["وإذا حللتم", "من إحرامكم."], ["أن صدّوكم", "لأجل أن صدّوكم."], ["البر والتقوى", "البر: كل طاعة لله ورسوله، والتقوى: فعل ما أمر الله به ورسوله وترك ما نهيا عنه."], ["الإثم والعدوان", "الإثم: سائر الذنوب، والعدوان: الظلم وتجاوز الحدود."], ["شديد العقاب", "عقابه شديد لا يُطاق."]], "m": "ينادي الله عباده المؤمنين: أوفوا بالعقود فلا تحلّوها، وبالعهود فلا تنكثوها، فلا تتركوا واجباً ولا ترتكبوا منهياً، ولا تحرّموا حلالاً ولا تحلّوا حراماً: أُحلّت لكم بهيمة الأنعام، الإبل والبقر والغنم، إلا ما يُتلى عليكم في الآية التالية، غير محلّي الصيد وأنتم محرمون، إن الله يحكم ما يريد فسلّموا له. ثم نهاهم عن إحلال شعائر الله بترك واجب أو فعل محرّم، ومن ذلك مناسك الحج والعمرة. ومن المنسوخ في الآية تحريم القتال في الشهر الحرام، وهدي المشركين وقلائدهم، فلا يُسمح لهم بدخول الحرم. وإذا تحلّلتم من إحرامكم فاصطادوا. ولا يحملنّكم بغض قوم صدّوكم يوم الحديبية عن المسجد الحرام أن تعتدوا عليهم بغير ما أذن الله. وتعاونوا على البر والتقوى، أي على أداء الواجبات والفضائل وترك المحرّمات والرذائل، ولا تعاونوا على الإثم والعدوان، واتقوا الله إن الله شديد العقاب.", "h": ["وجوب الوفاء بالعهود التي بين الله تعالى وبين العبد، والمحافظة على العقود التي بين العبد وأخيه؛ لشمول الآية ذلك.", "إباحة أكل لحوم الإبل والبقر والغنم إلا الميتة منها.", "تحريم الصيد في حال الإحرام وحلّيته بعد التحلّل، وهو صيد البر لا البحر.", "وجوب احترام شعائر الدين كلها، أداءً لما وجب أداؤه وتركاً لما وجب تركه.", "حرمة الاعتداء مطلقاً، حتى على الكافر.", "وجوب التعاون بين المؤمنين على إقامة الدين، وحرمة تعاونهم على المساس به."], "k": "«وتعاونوا على البر والتقوى»… من أتعاون معه اليوم على خير؟ وهل أعين أحداً على إثم ولو بكلمة؟"}, {"lbl": "الآية ٣", "q": "حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٣﴾", "w": [["وما أُهلّ لغير الله به", "ما ذُكر عليه اسم غير اسم الله، كاسم المسيح أو الولي."], ["المنخنقة", "التي خُنقت بحبل ونحوه فماتت."], ["الموقوذة", "المضروبة بعصا أو حجر فماتت."], ["المتردّية", "الساقطة من علٍ إلى أسفل فماتت."], ["النطيحة", "ما ماتت بسبب نطح أختها لها."], ["وما أكل السبع", "ما أكل منه الذئب وغيره من المفترسات."], ["إلا ما ذكّيتم", "ما أدركتم فيه الروح مستقرة فذكّيتموه بذبح أو نحر."], ["وما ذُبح على النُّصُب", "ما ذُبح على الأصنام المنصوبة، ومثلها ما ذُبح على أضرحة الأولياء وقبورهم."], ["وأن تستقسموا بالأزلام", "طلب معرفة ما قُسم من خير أو شر بالقداح، ومثله الكهانة وما يشبهها."], ["ذلكم فسق", "خروج عن طاعة الله ومعصية له."], ["فمن اضطُرّ", "من ألجأته ضرورة الجوع فخاف على نفسه الموت."], ["في مخمصة", "المخمصة: شدة الجوع حتى يضمر البطن."], ["غير متجانف لإثم", "غير مائل إلى المعصية، بأن يأكل قدر ما يسدّ رمقه ويدفع غائلة الجوع المهلك."]], "m": "هذه الآية تفصيل لقوله في أول السورة: «إلا ما يُتلى عليكم»، فذكر المحرّمات من اللحوم: الميتة، والدم، ولحم الخنزير، وما أُهلّ لغير الله به، والمنخنقة، والموقوذة، والمتردّية، والنطيحة، وما أكل السبع، إلا ما أدركتم فيه الروح مستقرة فذكّيتموه، وما ذُبح على النصب. وحرّم الاستقسام بالأزلام، وكانوا في الجاهلية يكتبون على قدح «أمرني ربي» وعلى آخر «نهاني ربي»، فيُجيلها المستقسم ويُخرج أحدها فيمضي أو يترك، فحرّمه الإسلام، وسنّ الاستخارة: ركعتين من غير الفريضة ثم الدعاء المعروف. ذلكم فسق. ثم أخبر أن الكافرين يئسوا اليوم من أن يردّوكم عن دينكم، بعد فتح مكة ودخول ثقيف وهوازن في الإسلام، فلا تخشوهم واخشوني بطاعتي ولزوم حدودي. اليوم أكملت لكم دينكم بجميع عقائده وعباداته وأحكامه وآدابه، وقد نزلت عشية عرفة في حجة الوداع، ولم يعش بعدها رسول الله ﷺ إلا إحدى وثمانين ليلة، وأتممت عليكم نعمتي فأمّنتكم بعد خوف وأعززتكم بعد ذل وهديتكم بعد ضلال، ورضيت لكم الإسلام ديناً. ثم رخّص لمن اضطرّه الجوع الشديد أن يأكل مما حرّم غير مائل إلى الإثم، فإن الله غفور رحيم.", "h": ["حرمة الميتة وما ذُكر معها، وهي عشر من المحرمات.", "حرمة الاستقسام بالأزلام، ومثلها قرعة الأنبياء وخط الرمل والكهانة وما أشبه ذلك.", "حرمة الذبح على القبور والقباب والنصب التذكارية، وهي من الشرك.", "جواز أكل ما أدركه المسلم حياً من الحيوان المأكول فذكّاه، وإن كان قد جُرح أو كُسر أو أشرف على الموت بأي سبب مميت.", "وجوب خشية الله تعالى، وحرمة خشية الكفار.", "حرمة الابتداع في الدين، وحرمة التشريع المنافي للشرع الإسلامي.", "جواز أكل الميتة لمن اضطُرّ من شدة الجوع فخاف على نفسه الهلاك، بشرط ألا يكون قاصداً المعصية مائلاً إلى الإثم."], "k": "«اليوم أكملت لكم دينكم»… الدين كامل، فهل أستغني به عن البدع، وأستخير الله بدل التطيّر والحظ؟"}, {"lbl": "الآيتان ٤ – ٥", "q": "يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿٤﴾ ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلّٞ لَّكُمۡ وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانٖۗ وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ ﴿٥﴾", "w": [["الطيبات", "ما أذن الله في أكله وأباحه لعباده المؤمنين."], ["مكلّبين", "مرسلين الجارحة على الصيد، كلباً كانت أو غيره."], ["طعام الذين أوتوا الكتاب", "ذبائح اليهود والنصارى."], ["المحصنات", "جمع محصنة، وهي العفيفة الحرة من النساء."], ["أجورهن", "مهورهن وصدقاتهن."], ["غير مسافحين", "غير مجاهرين بالزنى."], ["أخدان", "جمع خِدن، وهو الخليل والصاحب السرّي."], ["ومن يكفر بالإيمان", "يرتدّ عن الإيمان."], ["حبط عمله", "بطل كل ما قدّمه من الصالحات فلا يُثاب عليه."]], "m": "لما سأل بعض الصحابة عما يحل لهم، أنزل الله: يسألونك ماذا أُحلّ لهم؟ قل أُحلّ لكم الطيبات، وهي كل ما لذّ وطاب مما أباحه الله، وصيد ما علّمتم من الجوارح، كالكلاب والفهود والصقور، مرسلين لها على الصيد، تؤدّبونها بما علّمكم الله، وحدّ الجارحة المعلّمة: إذا أُرسلت ذهبت، وإذا زُجرت انزجرت، وإذا دُعيت أجابت. فكلوا مما أمسكن عليكم، واذكروا اسم الله عليه عند إرسالها، بشرط ألا تأكل منه، فإن أكلت فقد أمسكت لنفسها، إلا إن أُدرك حياً فذُكّي. واتقوا الله إن الله سريع الحساب. ثم قال: اليوم أُحلّ لكم الطيبات، وطعام الذين أوتوا الكتاب، أي ذبائح اليهود والنصارى، حلّ لكم، وطعامكم حلّ لهم، وأُحلّ لكم نكاح المحصنات العفائف من المؤمنات ومن الكتابيات، إذا آتيتموهن مهورهن، بعقد شرعي تام الشروط، لا مسافحين ولا متخذي أخدان سراً. ومن يكفر بعد إيمانه فقد حبط عمله، وهو في الآخرة من الخاسرين، وفيه إشارة إلى أن استباحة المحرّمات قد تؤدي إلى الكفر.", "h": ["مشروعية سؤال من لا يعلم عما ينبغي له أن يعلمه.", "حلّية الصيد إن توفّرت شروطه: أن يكون الجارح معلّماً، وأن يُذكر اسم الله عند إرساله، وألا يأكل منه، ويجوز أكل ما صيد برصاص أو آلة حادّة بشرط ذكر اسم الله عند رميه.", "إباحة طعام وذبائح أهل الكتاب.", "إباحة نكاح الكتابيات بشرط أن تكون حرة عفيفة، وأن يُعقد عليها العقد الشرعي القائم على الولي والشهود والمهر والصيغة.", "حرمة نكاح المتعة ونكاح الخلّة والصحبة الخاصة.", "المعاصي قد تقود إلى الكفر.", "المرتد عن الإسلام يحبط عمله، فلو راجع الإسلام لا يُثاب على ما فعله قبل الردة، وإن مات قبل العودة خسر نفسه وأهله يوم القيامة."], "k": "«قل أُحلّ لكم الطيبات»… الحلال واسع، فلماذا أتطلّع أحياناً إلى ما حرّم الله؟"}, {"lbl": "الآيتان ٦ – ٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٦﴾ وَٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ وَمِيثَٰقَهُ ٱلَّذِي وَاثَقَكُم بِهِۦٓ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٧﴾", "w": [["إذا قمتم إلى الصلاة", "إذا أردتم القيام إليها وأنتم على غير وضوء."], ["فاغسلوا وجوهكم", "بعد غسل الكفين ثلاثاً والمضمضة والاستنشاق والاستنثار، لبيان رسول الله ﷺ ذلك."], ["وأرجلكم إلى الكعبين", "واغسلوا أرجلكم إلى الكعبين، إلا أن يكون عليها خفّ ساتر لُبس بعد وضوء، فيُمسح عليه يوماً وليلة للمقيم، وثلاثة أيام للمسافر، بهذا جاءت السنة."], ["وإن كنتم جُنُباً", "الجنب: من قامت به جنابة، بالجماع أو خروج المني بلذة في نوم أو يقظة."], ["فاطّهّروا", "فاغتسلوا، والغسل: غسل سائر الجسد بالماء."], ["الغائط", "كناية عن الخارج من أحد السبيلين."], ["أو لامستم النساء", "كناية عن الجماع، ومن لامس امرأة ليتلذّذ بها انتقض وضوؤه."], ["فتيمّموا صعيداً", "اقصدوا تراباً أو حجراً أو رملاً أو سبخة مما صعد على وجه الأرض."], ["ميثاقه", "عهده المؤكد، والمراد شهادة أن لا إله إلا الله وأن محمداً رسول الله، إذ بها وجب الالتزام بسائر التكاليف."]], "m": "نادى الله عباده المؤمنين يأمرهم بالطهارة إذا أرادوا الصلاة، وهي مناجاة العبد لربه، فبيّن الطهارة الصغرى وهي الوضوء، والكبرى وهي الغسل، وما ينوب عنهما عند العجز وهو التيمم: فاغسلوا وجوهكم، وحدّ الوجه طولاً من منبت الشعر إلى منتهى الذقن، وعرضاً من الأذن إلى الأذن، وأيديكم إلى المرافق فيدخل المرفقان، وامسحوا برؤوسكم، والسنة بيّنت أن يُقبل بيديه ويُدبر فيمسح جميع رأسه ثم أذنيه، وأرجلكم إلى الكعبين، وبيّنت السنة المسح على الخفين، والترتيب، والموالاة، والنية، والتسمية. وإن كنتم جنباً فاغتسلوا، وانقطاع دم الحيض والنفاس كالجنابة. وإن كنتم مرضى يضرّكم الماء، أو على سفر، أو جاء أحد منكم من الغائط، أو لامستم النساء، فلم تجدوا ماء، فتيمّموا صعيداً طيباً طاهراً، فاضربوا بالكفين الأرض وامسحوا الوجه والكفين مرة واحدة. ما يريد الله ليجعل عليكم من حرج، ولكن يريد ليطهّركم من الأحداث والذنوب، إذ الوضوء كفّارة للذنوب، وليتمّ نعمته عليكم لعلكم تشكرون. ثم أمرهم أن يذكروا نعمته عليهم بالهداية، وميثاقه الذي واثقهم به إذ قالوا: سمعنا وأطعنا، قالها الصحابة حين بايعوا رسول الله ﷺ، وقالها كل مسلم بلسان الحال لما شهد الشهادتين، واتقوا الله إن الله عليم بذات الصدور.", "h": ["الأمر بالطهارة، وبيان كيفية الوضوء، وكيفية الغسل، وكيفية التيمم.", "بيان الأعذار الناقلة للمؤمن من الوضوء إلى التيمم.", "بيان موجبات الوضوء والغسل.", "الشكر هو علة الإنعام.", "ذكر العهود يساعد على التزامها والمحافظة عليها."], "k": "«ولكن يريد ليطهّركم»… هل أستحضر في وضوئي القادم أنه يطهّرني من ذنوبي أيضاً؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;